const currentRates = $input.first().json;
const previousRates = $input.all()[1].json;

const rateChanges = [];

// Calculate changes for each loan type
const loanTypes = ['conventional30', 'conventional15', 'fha30', 'va30', 'jumbo30'];

loanTypes.forEach(loanType => {
  const current = parseFloat(currentRates[loanType]);
  const previous = parseFloat(previousRates[loanType]);
  const change = current - previous;

  if (Math.abs(change) >= 0.125) { // Significant change threshold
    rateChanges.push({
      loanType,
      currentRate: current,
      previousRate: previous,
      change: change,
      changePercent: ((change / previous) * 100).toFixed(3),
      isDecrease: change < 0,
      alertLevel: Math.abs(change) >= 0.25 ? 'major' : 'minor'
    });
  }
});

if (rateChanges.length > 0) {
  return [{ json: { rateChanges, timestamp: new Date().toISOString() } }];
} else {
  // No significant rate changes
  return [];
}

const lead = $json;
const rateChanges = $node['Calculate Rate Changes'].json.rateChanges;

// Find the relevant rate change for this lead's loan type
const leadLoanType = lead.customFields.loanType || 'conventional30';
const relevantChange = rateChanges.find(change => 
  change.loanType === leadLoanType || 
  change.loanType === 'conventional30' // default fallback
);

if (!relevantChange || !relevantChange.isDecrease) {
  return []; // Skip if no rate decrease for this loan type
}

const loanAmount = parseFloat(lead.customFields.loanAmount) || 300000;
const originalRate = parseFloat(lead.customFields.quotedRate) || relevantChange.previousRate;
const newRate = relevantChange.currentRate;
const rateDrop = originalRate - newRate;

// Calculate monthly payment difference
const monthlyRateOld = originalRate / 100 / 12;
const monthlyRateNew = newRate / 100 / 12;
const loanTermMonths = 360; // 30 years

const oldPayment = (loanAmount * (monthlyRateOld * Math.pow(1 + monthlyRateOld, loanTermMonths))) / (Math.pow(1 + monthlyRateOld, loanTermMonths) - 1);
const newPayment = (loanAmount * (monthlyRateNew * Math.pow(1 + monthlyRateNew, loanTermMonths))) / (Math.pow(1 + monthlyRateNew, loanTermMonths) - 1);

const monthlySavings = oldPayment - newPayment;
const lifetimeSavings = monthlySavings * loanTermMonths;

return [{
  json: {
    ...lead,
    rateAlert: {
      originalRate: originalRate.toFixed(3),
      newRate: newRate.toFixed(3),
      rateDrop: rateDrop.toFixed(3),
      oldPayment: Math.round(oldPayment),
      newPayment: Math.round(newPayment),
      monthlySavings: Math.round(monthlySavings),
      lifetimeSavings: Math.round(lifetimeSavings),
      alertLevel: relevantChange.alertLevel,
      loanType: leadLoanType
    }
  }
}];
